class Record:
    def __init__(self, values: Dict[str, Any]):
        self.values = values

    def data(self, *keys: Union[int, str]) -> Dict[str, Any]:
        result = {}
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self.values):
                    raise IndexError(f"Index {key} out of bounds for Record with len({len(self.values)})")
                result[self.values.keys()[key]] = self.values.values()[key]
            elif isinstance(key, str):
                result[key] = self.values.get(key, None)
            else:
                raise TypeError("Key must be an integer or a string.")
        return result

