    for i, ordering in enumerate(orderings):
        for item in ordering:
            if item in result:
                result[item].append(i)
            else:
                result[item] = [i]

    ordered_items = sorted(result, key=lambda item: len(result[item]))

    merged_orderings = []

    for item in ordered_items:
        merged_orderings.append(item)
        for idx in result[item]:
            if idx != len(orderings) - 1:
                next_ordering = [item] + orders[idx+1]
                merged_orderings.append(next_ordering)
