import collections

@classmethod
def protocol_handlers(cls, protocol_version=None):
    # Define a dictionary of available Bolt protocol handlers
    protocol_handlers = {
        (3, 5): BoltProtocolVersion35,
        (3, 6): BoltProtocolVersion36,
        (3, 7): BoltProtocolVersion37,
        (4, 0): BoltProtocolVersion40
    }

    # If an explicit protocol version is provided, filter the dictionary
    if protocol_version:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be a tuple")
        if protocol_version not in protocol_handlers:
            raise ValueError(f"Protocol version {protocol_version} is not supported")
        return {protocol_version: protocol_handlers[protocol_version]}

    # Return all available versions if no protocol version is provided
    return protocol_handlers

