from typing import Optional, Tuple

def find_tags(text: str, replacer: Optional[callable] = None) -> Tuple[set, str]:
    import re

    # Regular expression to find tags
    regex = r'\b\w+\b'

    # Find all tags in the text
    tags = set(re.findall(regex, text))

    # Create a dictionary to store tag replacements if a replacer is provided
    if replacer:
        tags_to_replace = {tag: replacer(tag) for tag in tags}

    # Replace tags in the text with their replacements if a replacer is provided
    if replacer:
        text = re.sub(r'\b\w+\b', lambda match: tags_to_replace.get(match.group(0), match.group(0)), text)

    return (tags, text)

