from colorama import Fore

def process_text_links(text):
    link_pattern = r"\b(https?://[^\s]+)\b"
    updated_text = text

    for match in re.finditer(link_pattern, text):
        link = match.group(1)
        parsed_url = urlparse(link)
        linkText = parsed_url.path
        if parsed_url.scheme == "http":
            color = Fore.WHITE
        elif parsed_url.scheme == "https":
            color = Fore.BLUE
        elif parsed_url.scheme == "ftp":
            color = Fore.RED
        elif parsed_url.scheme == "mailto":
            color = Fore.YELLOW
        else:
            color = Fore.CYAN

        updated_text = updated_text.replace(match.group(0), f"{color}{linkText}{Style.RESET_ALL}")
        updated_text = updated_text.replace(f"{color}{linkText}{Style.RESET_ALL}", f"{Fore.WHITE}[{linkText}]{Style.RESET_ALL}", 1)

    return updated_text

