from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    document = document.lower()
    if not document.startswith("xrd="):
        try:
            payload = json.loads(document)
            if 'subject' not in payload or 'owner' not in payload:
                return {}
            return payload
        except json.JSONDecodeError:
            return {}
    else:
        xrd_url = urlparse(document)
        if xrd_url.scheme != 'https' or xrd_url.netloc != 'diaspora社群':
            return {}
        return xrd_url.query_params

